script:
(function () {
  'use strict';
  // Investment goal: the regular investment needed to reach a target under three return
  // scenarios (low / expected / high), shown side by side, plus the return your planned amount needs.
  //   Each scenario's yearly return r is an effective annual rate. A yearly tax rate t on growth
  //   (taxable account) lowers it to r' = r x (1 - t). Per-period rate i = (1 + r')^(1/f) - 1 for
  //   f contributions a year. Contributions rise by c% at the start of each year; deposits at the
  //   end (or start) of each period. Ending value is linear in the first-year contribution C:
  //     FV = A + C x U, A = current amount grown, U = ending value of $1-a-period contributions,
  //   so the required C = (goal - A) / U (zero if A already reaches the goal).
  //   A goal in today's dollars is grown by inflation: goal x (1 + inflation)^years.
  //   Return needed for the planned amount: bisection on r over -90% .. 100% (FV rises with r).
  // Verified (Node, scratch tests): $100,000 goal, 10 years, nothing invested, 6%, annual deposits
  //   at year end -> $7,586.80 a year (100,000 x 0.06 / (1.06^10 - 1)); monthly at 6% effective ->
  //   monthly rate 0.486755%, $615.49 a month (100,000 x i / ((1 + i)^120 - 1));
  //   0% return -> goal / number of deposits ($833.33 a month);
  //   $50,000 already invested at 8% for 10 years -> $107,946.25, goal $100,000 needs $0;
  //   annuity-due check: annual at start, 6%, 10 years -> $7,157.35 (= 7,586.80 / 1.06);
  //   planned $7,586.80 a year -> return needed 6.00%; 8% with a 25% tax on growth -> same as 6%;
  //   today's-dollar goal $100,000, 2% inflation, 10 years -> $121,899.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  var money2 = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });
  var PERIOD_WORD = { 12: 'month', 4: 'quarter', 1: 'year' };

  function num(id) {
    var el = document.getElementById(id);
    var v = el ? parseFloat(el.value) : NaN;
    return isNaN(v) ? NaN : v;
  }
  function set(id, text) { var el = document.getElementById(id); if (el) el.textContent = text; }
  function pctText(v) { return (Math.round(v * 10000) / 100).toFixed(2) + '%'; }
  function signed(v) { return v < 0 ? '−' + money.format(-v) : '+' + money.format(v); }

  // Simulate the account: returns ending value and year-end balances.
  function simulate(o, annualRate, contribution) {
    var i = Math.pow(1 + annualRate, 1 / o.freq) - 1;
    var bal = o.current, invested = o.current, rows = [];
    for (var y = 1; y <= o.years; y++) {
      var amt = contribution * Math.pow(1 + o.raise, y - 1);
      for (var p = 0; p < o.freq; p++) {
        if (o.atStart) { bal += amt; bal *= 1 + i; } else { bal *= 1 + i; bal += amt; }
        invested += amt;
      }
      rows.push({ year: y, invested: invested, balance: bal });
    }
    return { balance: bal, invested: invested, rows: rows };
  }

  function required(o, annualRate) {
    var a = simulate(o, annualRate, 0).balance;
    var u = simulate(Object.assign({}, o, { current: 0 }), annualRate, 1).balance;
    if (a >= o.goal) return 0;
    return u > 0 ? (o.goal - a) / u : NaN;
  }

  function rateNeeded(o, contribution) {
    // Pre-tax annual return so that the planned amount reaches the goal.
    var keep = 1 - o.tax;
    function f(r) { return simulate(o, r * keep, contribution).balance - o.goal; }
    var lo = -0.9, hi = 1;
    if (f(lo) >= 0) return { below: true };
    if (f(hi) < 0) return { above: true };
    for (var k = 0; k < 200; k++) {
      var mid = (lo + hi) / 2;
      if (f(mid) >= 0) hi = mid; else lo = mid;
    }
    return { rate: (lo + hi) / 2 };
  }

  function update() {
    var o = {
      goalInput: num('igGoal'), years: Math.round(num('igYears')), current: num('igCurrent'),
      freq: parseInt(document.getElementById('igFreq').value, 10),
      atStart: document.getElementById('igTiming').value === 'start',
      tax: num('igTax') / 100, raise: num('igRaise') / 100, inflation: num('igInflation') / 100,
      today: document.getElementById('igToday').checked
    };
    var low = num('igLow') / 100, mid = num('igMid') / 100, high = num('igHigh') / 100, planned = num('igPlanned');
    var error = document.getElementById('igError');
    var vals = [o.goalInput, o.years, o.current, o.tax, o.raise, o.inflation, low, mid, high, planned];
    var msg = '';
    if (vals.some(isNaN)) msg = 'Fill in every field with a number.';
    else if (o.goalInput <= 0) msg = 'Enter a goal above $0.';
    else if (o.years < 1 || o.years > 60) msg = 'Enter from 1 to 60 years.';
    else if (o.current < 0 || planned < 0) msg = 'Amounts cannot be negative.';
    else if ([low, mid, high].some(function (r) { return r < -0.5 || r > 0.5; })) msg = 'Enter yearly returns from -50% to 50%.';
    else if (o.tax < 0 || o.tax > 0.6) msg = 'Enter a tax rate from 0% to 60%.';
    else if (o.raise < 0 || o.raise > 0.2) msg = 'Enter a yearly increase from 0% to 20%.';
    else if (o.inflation < 0 || o.inflation > 0.2) msg = 'Enter an inflation rate from 0% to 20%.';
    error.hidden = !msg;
    error.textContent = msg;
    if (msg) return;

    o.goal = o.today ? o.goalInput * Math.pow(1 + o.inflation, o.years) : o.goalInput;
    var word = PERIOD_WORD[o.freq] || 'period';
    var keep = 1 - o.tax;
    var scen = [['Low', low], ['Expected', mid], ['High', high]].map(function (s) {
      var net = s[1] * keep;
      var c = required(o, net);
      var need = isFinite(c) ? simulate(o, net, c) : null;
      var plan = simulate(o, net, planned);
      return { name: s[0], rate: s[1], net: net, c: c, invested: need ? need.invested : NaN, plan: plan, rows: need ? need.rows : [] };
    });
    var exp = scen[1];

    set('igNeed', isFinite(exp.c) ? money2.format(exp.c) + ' a ' + word : '–');
    set('igNeedLow', isFinite(scen[0].c) ? money2.format(scen[0].c) : '–');
    set('igNeedHigh', isFinite(scen[2].c) ? money2.format(scen[2].c) : '–');
    var rn = rateNeeded(o, planned);
    set('igRateNeeded', planned === 0 && o.current === 0 ? 'Enter a planned amount' : rn.below ? 'Under -90% (already enough)' : rn.above ? 'Over 100% a year' : pctText(rn.rate) + ' a year');
    set('igGoalFuture', money.format(o.goal));
    set('igPlanEnd', money.format(exp.plan.balance));
    set('igPlanGap', signed(exp.plan.balance - o.goal));
    var note = document.getElementById('igNote');
    if (exp.c === 0) {
      note.hidden = false;
      note.textContent = 'At the expected return, what you have already invested reaches the goal without any more contributions.';
    } else note.hidden = true;

    document.getElementById('igScenarioBody').innerHTML = scen.map(function (s) {
      return '<tr><th scope="row">' + s.name + '</th><td>' + pctText(s.rate) + (o.tax > 0 ? ' (' + pctText(s.net) + ' after tax)' : '') +
        '</td><td>' + (isFinite(s.c) ? money2.format(s.c) : '–') + '</td><td>' + (isFinite(s.invested) ? money.format(s.invested) : '–') +
        '</td><td>' + money.format(s.plan.balance) + '</td><td>' + signed(s.plan.balance - o.goal) + '</td></tr>';
    }).join('');
    set('igColNeed', 'Needed each ' + word);

    // Year-by-year: the expected-case contribution, grown at each scenario's return.
    var c = isFinite(exp.c) ? exp.c : 0;
    var lowRun = simulate(o, scen[0].net, c), midRun = simulate(o, exp.net, c), highRun = simulate(o, scen[2].net, c);
    set('igYearIntro', 'Investing ' + money2.format(c) + ' a ' + word + ' (the expected-case amount' +
      (o.raise > 0 ? ', rising ' + pctText(o.raise) + ' a year' : '') + '), here is how the balance could grow if returns come in low, as expected or high.');
    document.getElementById('igYearBody').innerHTML = midRun.rows.map(function (r, k) {
      return '<tr><td>' + r.year + '</td><td>' + money.format(r.invested) + '</td><td>' + money.format(lowRun.rows[k].balance) +
        '</td><td>' + money.format(r.balance) + '</td><td>' + money.format(highRun.rows[k].balance) + '</td></tr>';
    }).join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('igForm');
    if (!form) return;
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
